import{_t as e,it as t,n,rt as r}from"./chunks/framework.B5d4da8a.js";var i=JSON.parse(`{"title":"Dependent types in handl","description":"","frontmatter":{},"headers":[],"relativePath":"handl/tutorials/dependent-types.md","filePath":"vendored/handl/tutorials/dependent-types.md"}`),a={name:`handl/tutorials/dependent-types.md`};function o(n,i,a,o,s,c){return e(),r(`div`,null,[...i[0]||=[t(`<h1 id="dependent-types-in-handl" tabindex="-1">Dependent types in handl <a class="header-anchor" href="#dependent-types-in-handl" aria-label="Permalink to “Dependent types in handl”">​</a></h1><p>In this tutorial you will write a <strong>length-indexed vector</strong> in handl — the canonical dependent-types example — and use the features that make it work: <code>data</code> families, index arithmetic, <code>match</code> refinement, <code>Path</code>/<code>transport</code>/<code>J</code>, <code>IO(sig)</code> handlers, and implicit <code>{…}</code> binders.</p><p>Every step is a small <code>.hnl</code> file you can check with <code>hnl typecheck</code> and (where noted) run with <code>hnl run</code>. Along the way you will intentionally break one file to see what a real type error looks like.</p><h2 id="what-you-will-learn" tabindex="-1">What you will learn <a class="header-anchor" href="#what-you-will-learn" aria-label="Permalink to “What you will learn”">​</a></h2><ul><li>How to declare an indexed <code>data</code> family and its constructors.</li><li>How annotations like <code>Vec(1 + 1, Bool)</code> are <em>computed</em> at check time.</li><li>How <code>match</code> refines the scrutinee&#39;s index per branch — and rejects unreachable arms.</li><li>How <code>Path</code>, <code>refl</code>, <code>p # v</code> (transport), and <code>J</code> work as the equality layer.</li><li>How <code>IO(sig)</code> types effectful functions and how <code>handle … with</code> discharges them.</li><li>How <code>{…}</code> binders declare implicit type-level parameters.</li></ul><h2 id="prerequisites" tabindex="-1">Prerequisites <a class="header-anchor" href="#prerequisites" aria-label="Permalink to “Prerequisites”">​</a></h2><ul><li>A working <code>hnl</code> binary (see <a href="./setup.html">Set up the platform</a>).</li><li>Familiarity with the arrow surface: <code>x ~&gt; body</code> is a function, <code>name : Type = value</code> is an annotated binding.</li></ul><h2 id="step-1-declare-a-data-family" tabindex="-1">Step 1: Declare a <code>data</code> family <a class="header-anchor" href="#step-1-declare-a-data-family" aria-label="Permalink to “Step 1: Declare a data family”">​</a></h2><p>Create <code>vec.hnl</code>:</p><div class="language-hnl"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">hnl</span><pre class="shiki shiki-themes handl-dark github-light" style="--shiki-dark:#ffffff;--shiki-light:#24292e;--shiki-dark-bg:#2a2a2a;--shiki-light-bg:#fff;" tabindex="0" dir="ltr"><code><span class="line"><span>data Vec(n : Nat, a : Type) :: VNil : Vec(0, a) | VCons(x : a, xs : Vec(n, a)) : Vec(n + 1, a)</span></span></code></pre></div><p>Read it as: <code>Vec</code> is a family of types indexed by a natural number <code>n</code> and a payload type <code>a</code>. It has two constructors:</p><ul><li><code>VNil</code> — the empty vector, at index <code>Vec(0, a)</code>.</li><li><code>VCons(x, xs)</code> — pushes an <code>a</code> onto a <code>Vec(n, a)</code>, producing a <code>Vec(n + 1, a)</code>. The result index is an <em>index term</em>, not just a variable — <code>n + 1</code> is evaluated by the checker.</li></ul><p>Check it:</p><div class="language-text"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes handl-dark github-light" style="--shiki-dark:#ffffff;--shiki-light:#24292e;--shiki-dark-bg:#2a2a2a;--shiki-light-bg:#fff;" tabindex="0" dir="ltr"><code><span class="line"><span>$ hnl typecheck vec.hnl</span></span>
<span class="line"><span>vec.hnl: ok: {&quot;__registry__&quot;:&quot;handl.canonical&quot;,&quot;__tag__&quot;:&quot;type.unit&quot;}</span></span></code></pre></div><p>A <code>data</code> declaration produces no value, so the module checks to <code>type.unit</code>.</p><h2 id="step-2-construct-and-annotate-values" tabindex="-1">Step 2: Construct and annotate values <a class="header-anchor" href="#step-2-construct-and-annotate-values" aria-label="Permalink to “Step 2: Construct and annotate values”">​</a></h2><p>Append to <code>vec.hnl</code>:</p><div class="language-hnl"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">hnl</span><pre class="shiki shiki-themes handl-dark github-light" style="--shiki-dark:#ffffff;--shiki-light:#24292e;--shiki-dark-bg:#2a2a2a;--shiki-light-bg:#fff;" tabindex="0" dir="ltr"><code><span class="line"><span>v : Vec(2, Bool) = VCons(true, VCons(false, VNil))</span></span>
<span class="line"><span>w : Vec(1 + 1, Bool) = v</span></span></code></pre></div><div class="language-text"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes handl-dark github-light" style="--shiki-dark:#ffffff;--shiki-light:#24292e;--shiki-dark-bg:#2a2a2a;--shiki-light-bg:#fff;" tabindex="0" dir="ltr"><code><span class="line"><span>$ hnl typecheck vec.hnl</span></span>
<span class="line"><span>vec.hnl: ok: {&quot;__registry__&quot;:&quot;handl.canonical&quot;,&quot;__tag__&quot;:&quot;type.unit&quot;}</span></span></code></pre></div><p>Two things happened:</p><ul><li><code>VCons(true, VCons(false, VNil))</code> synthesizes <code>Vec(1 + 1, Bool)</code> — <code>VNil</code> is <code>Vec(0, Bool)</code>, each <code>VCons</code> adds one. That is <em>definitionally</em> equal to <code>Vec(2, Bool)</code>, so <code>v</code> checks.</li><li><code>w</code>&#39;s annotation computes <code>1 + 1</code> to <code>2</code>, so it accepts <code>v</code>. Index arithmetic (<code>+</code>, <code>-</code>, <code>*</code>) is normalized by the checker — <code>Vec(n+m)</code> and <code>Vec(m+n)</code> are the same type.</li></ul><p>Constructor values are ordinary values too, so this file also runs:</p><div class="language-text"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes handl-dark github-light" style="--shiki-dark:#ffffff;--shiki-light:#24292e;--shiki-dark-bg:#2a2a2a;--shiki-light-bg:#fff;" tabindex="0" dir="ltr"><code><span class="line"><span>$ hnl run vec.hnl   # prints the tagged constructor value for \`v\`/\`w\`</span></span></code></pre></div><h2 id="step-3-see-a-real-error" tabindex="-1">Step 3: See a real error <a class="header-anchor" href="#step-3-see-a-real-error" aria-label="Permalink to “Step 3: See a real error”">​</a></h2><p>Change <code>v</code>&#39;s annotation to a wrong length:</p><div class="language-hnl"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">hnl</span><pre class="shiki shiki-themes handl-dark github-light" style="--shiki-dark:#ffffff;--shiki-light:#24292e;--shiki-dark-bg:#2a2a2a;--shiki-light-bg:#fff;" tabindex="0" dir="ltr"><code><span class="line"><span>v : Vec(3, Bool) = VCons(true, VCons(false, VNil))</span></span></code></pre></div><div class="language-text"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes handl-dark github-light" style="--shiki-dark:#ffffff;--shiki-light:#24292e;--shiki-dark-bg:#2a2a2a;--shiki-light-bg:#fff;" tabindex="0" dir="ltr"><code><span class="line"><span>$ hnl typecheck vec.hnl</span></span>
<span class="line"><span>vec.hnl:2:20: error [typecheck]: cannot unify — expected Vec(3, Bool), got Vec(1 + 1, Bool)</span></span></code></pre></div><p>The diagnostic points at the annotated expression (<code>2:20</code>) and renders both sides in surface syntax — <code>Vec(3, Bool)</code> vs the synthesized <code>Vec(1 + 1, Bool)</code> — not internal encodings. Revert the annotation to <code>Vec(2, Bool)</code> before continuing.</p><h2 id="step-4-match-refines-the-index-per-branch" tabindex="-1">Step 4: <code>match</code> refines the index per branch <a class="header-anchor" href="#step-4-match-refines-the-index-per-branch" aria-label="Permalink to “Step 4: match refines the index per branch”">​</a></h2><p>Add a <code>head</code> binding that only accepts non-empty vectors:</p><div class="language-hnl"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">hnl</span><pre class="shiki shiki-themes handl-dark github-light" style="--shiki-dark:#ffffff;--shiki-light:#24292e;--shiki-dark-bg:#2a2a2a;--shiki-light-bg:#fff;" tabindex="0" dir="ltr"><code><span class="line"><span>head : Bool = match v { VCons(x, xs): x }</span></span></code></pre></div><div class="language-text"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes handl-dark github-light" style="--shiki-dark:#ffffff;--shiki-light:#24292e;--shiki-dark-bg:#2a2a2a;--shiki-light-bg:#fff;" tabindex="0" dir="ltr"><code><span class="line"><span>$ hnl typecheck vec.hnl   # ok</span></span>
<span class="line"><span>$ hnl run vec.hnl         # prints: true</span></span></code></pre></div><p><code>match</code> on a family value does <strong>dependent elimination</strong>: in each arm the scrutinee&#39;s index is refined to that constructor&#39;s result index. You can see the flip side by adding the <code>VNil</code> arm back:</p><div class="language-hnl"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">hnl</span><pre class="shiki shiki-themes handl-dark github-light" style="--shiki-dark:#ffffff;--shiki-light:#24292e;--shiki-dark-bg:#2a2a2a;--shiki-light-bg:#fff;" tabindex="0" dir="ltr"><code><span class="line"><span>head : Bool = match v { VNil: false, VCons(x, xs): x }</span></span></code></pre></div><div class="language-text"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes handl-dark github-light" style="--shiki-dark:#ffffff;--shiki-light:#24292e;--shiki-dark-bg:#2a2a2a;--shiki-light-bg:#fff;" tabindex="0" dir="ltr"><code><span class="line"><span>vec.hnl:4:8: error [typecheck]: match: unreachable constructor arm (decided index mismatch)</span></span></code></pre></div><p><code>v</code> is <code>Vec(2, Bool)</code> — a <code>VNil</code> (<code>Vec(0)</code>) arm can never match, so the arm is rejected as unreachable rather than silently kept. Inside a function whose index is a <em>variable</em> (<code>n</code> instead of <code>2</code>), both arms stay reachable and each gets its own refined index: under <code>VNil</code> the checker knows <code>n ≡ 0</code>; under <code>VCons</code> it knows <code>n ≡ k + 1</code> for some <code>k</code>.</p><h2 id="step-5-motives-path-refl-and-transport" tabindex="-1">Step 5: Motives, <code>Path</code>, <code>refl</code>, and transport <a class="header-anchor" href="#step-5-motives-path-refl-and-transport" aria-label="Permalink to “Step 5: Motives, Path, refl, and transport”">​</a></h2><p>When the <em>result type</em> depends on the scrutinee, give <code>match</code> an explicit <strong>motive</strong> with <code>return … with</code>:</p><div class="language-hnl"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">hnl</span><pre class="shiki shiki-themes handl-dark github-light" style="--shiki-dark:#ffffff;--shiki-light:#24292e;--shiki-dark-bg:#2a2a2a;--shiki-light-bg:#fff;" tabindex="0" dir="ltr"><code><span class="line"><span>id_vec : Pi(Nat, n ~&gt; Pi(Vec(n + 0, Bool), v ~&gt; Vec(n + 0, Bool))) =</span></span>
<span class="line"><span>  n ~&gt; v ~&gt; match v return (i, w) ~&gt; Vec(i, Bool) with {</span></span>
<span class="line"><span>    VNil: eq_n # v,</span></span>
<span class="line"><span>    VCons(x, xs): eq_n # v,</span></span>
<span class="line"><span>  }</span></span></code></pre></div><div class="language-text"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes handl-dark github-light" style="--shiki-dark:#ffffff;--shiki-light:#24292e;--shiki-dark-bg:#2a2a2a;--shiki-light-bg:#fff;" tabindex="0" dir="ltr"><code><span class="line"><span>$ hnl typecheck vec.hnl   # ok</span></span></code></pre></div><ul><li><code>Pi(A, x ~&gt; B)</code> is a dependent function type: &quot;for <code>x : A</code>, produce a <code>B</code>&quot;. <code>id_vec</code> takes <code>n : Nat</code>, then a <code>Vec(n + 0, Bool)</code>, and returns the same type.</li><li><code>return (i, w) ~&gt; Vec(i, Bool)</code> is the motive — the result type, parameterized by the refined index <code>i</code> and the scrutinee <code>w</code>.</li><li>In each arm the checker binds a <strong><code>Path</code> witness</strong> named <code>eq_&lt;index&gt;</code>: under <code>VNil</code>, <code>eq_n : Path(n, 0)</code>; under <code>VCons</code>, <code>eq_n : Path(n, k + 1)</code>. <code>eq_n # v</code> <strong>transports</strong> <code>v</code> along that path, rewriting its type to what the motive needs.</li></ul><p><code>Path(a, b)</code> is the equality type; <code>refl</code> is the proof that <code>a ≡ b</code> when the endpoints decide equal:</p><div class="language-hnl"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">hnl</span><pre class="shiki shiki-themes handl-dark github-light" style="--shiki-dark:#ffffff;--shiki-light:#24292e;--shiki-dark-bg:#2a2a2a;--shiki-light-bg:#fff;" tabindex="0" dir="ltr"><code><span class="line"><span>v : Vec(2, Bool) = VCons(true, VCons(false, VNil))</span></span>
<span class="line"><span>p : Path(2, 2) = refl</span></span>
<span class="line"><span>w : Vec(2, Bool) = p # v      -- transport along p</span></span>
<span class="line"><span>w2 : Vec(2, Bool) = refl # v  -- refl is the identity transport</span></span></code></pre></div><p>A false equation is rejected:</p><div class="language-hnl"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">hnl</span><pre class="shiki shiki-themes handl-dark github-light" style="--shiki-dark:#ffffff;--shiki-light:#24292e;--shiki-dark-bg:#2a2a2a;--shiki-light-bg:#fff;" tabindex="0" dir="ltr"><code><span class="line"><span>bad : Path(2, 3) = refl</span></span>
<span class="line"><span>-- error [typecheck]: refl cannot prove Path(Number(2), Number(3)) — decided inequality</span></span></code></pre></div><p><code>J</code> is the general path eliminator — same job as <code>p # v</code>, with the motive spelled out as an argument instead of <code>return … with</code>:</p><div class="language-hnl"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">hnl</span><pre class="shiki shiki-themes handl-dark github-light" style="--shiki-dark:#ffffff;--shiki-light:#24292e;--shiki-dark-bg:#2a2a2a;--shiki-light-bg:#fff;" tabindex="0" dir="ltr"><code><span class="line"><span>id_vec : Pi(Nat, n ~&gt; Pi(Vec(n + 0, Bool), v ~&gt; Vec(n + 0, Bool))) =</span></span>
<span class="line"><span>  n ~&gt; v ~&gt; match v return (i, w) ~&gt; Vec(i, Bool) with {</span></span>
<span class="line"><span>    VNil: J eq_n, (i2, w2) ~&gt; Vec(i2, Bool), v,</span></span>
<span class="line"><span>    VCons(x, xs): J eq_n, (i2, w2) ~&gt; Vec(i2, Bool), v,</span></span>
<span class="line"><span>  }</span></span></code></pre></div><blockquote><p><strong>Type-level only.</strong> <code>Path</code>, <code>refl</code>, <code>#</code> transport, and <code>J</code> are proof machinery — they exist so the <em>checker</em> can rewrite types. <code>hnl typecheck</code> verifies them; <code>hnl run</code> does not give them a computational meaning (transported values evaluate to their payload).</p></blockquote><h2 id="step-6-io-sig-and-handle-with" tabindex="-1">Step 6: <code>IO(sig)</code> and <code>handle … with</code> <a class="header-anchor" href="#step-6-io-sig-and-handle-with" aria-label="Permalink to “Step 6: IO(sig) and handle … with”">​</a></h2><p><code>IO</code> is a former indexed by an <strong>operation signature</strong> — a record naming the ops a computation may perform:</p><div class="language-hnl"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">hnl</span><pre class="shiki shiki-themes handl-dark github-light" style="--shiki-dark:#ffffff;--shiki-light:#24292e;--shiki-dark-bg:#2a2a2a;--shiki-light-bg:#fff;" tabindex="0" dir="ltr"><code><span class="line"><span>print : String ~&gt; IO({puts: String ~&gt; Unit}) = s ~&gt; print(s)</span></span></code></pre></div><p><code>print</code> returns an <code>IO</code> whose sig declares one op, <code>puts</code>, taking a <code>String</code> and returning <code>Unit</code>. Signature subtyping is record-width: an <code>IO({puts})</code> value checks wherever a wider <code>IO({puts, gets})</code> is expected — a caller is only <em>allowed</em> more ops than the callee uses.</p><p><code>handle &lt;expr&gt; with { op: impl, … }</code> discharges ops. A covered op&#39;s sig entry is replaced by the impl&#39;s return type:</p><div class="language-hnl"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">hnl</span><pre class="shiki shiki-themes handl-dark github-light" style="--shiki-dark:#ffffff;--shiki-light:#24292e;--shiki-dark-bg:#2a2a2a;--shiki-light-bg:#fff;" tabindex="0" dir="ltr"><code><span class="line"><span>puts_impl : (String ~&gt; Unit) ~&gt; Unit = req ~&gt; req(&quot;x&quot;)</span></span>
<span class="line"><span>x : IO({puts: Unit}) = handle print(&quot;x&quot;) with {puts: puts_impl}</span></span></code></pre></div><p>Coverage is checked both ways — a handler naming ops the body never uses, or covering none of them, is an error; uncovered ops pass through to the residual <code>IO</code> for an outer handler. <code>handle f with h</code> also works on an arrow itself (deep handler), producing <code>A ~&gt; IO(S&#39;)</code>.</p><blockquote><p><strong>Type-level note.</strong> The annotations and coverage rules above are enforced by <code>hnl typecheck</code>. Running a <code>handle</code> expression interprets the declared ops at runtime — it needs real op implementations, so toy handlers like the one above are check-time illustrations.</p></blockquote><h2 id="step-7-implicit-binders" tabindex="-1">Step 7: Implicit <code>{…}</code> binders <a class="header-anchor" href="#step-7-implicit-binders" aria-label="Permalink to “Step 7: Implicit {…} binders”">​</a></h2><p>Prefix a name&#39;s binders with <code>{name}</code> (optionally <code>{name : Sort}</code>) to make it an <strong>implicit index/type parameter</strong>: callers never pass it; the checker inserts a fresh metavariable at each application and unification solves it.</p><div class="language-hnl"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">hnl</span><pre class="shiki shiki-themes handl-dark github-light" style="--shiki-dark:#ffffff;--shiki-light:#24292e;--shiki-dark-bg:#2a2a2a;--shiki-light-bg:#fff;" tabindex="0" dir="ltr"><code><span class="line"><span>id_io{s} : (String ~&gt; IO(s)) ~&gt; String ~&gt; IO(s) = f ~&gt; x ~&gt; f(x)</span></span>
<span class="line"><span>y : IO({puts: String ~&gt; Unit}) = id_io(print)(&quot;x&quot;)</span></span></code></pre></div><div class="language-text"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes handl-dark github-light" style="--shiki-dark:#ffffff;--shiki-light:#24292e;--shiki-dark-bg:#2a2a2a;--shiki-light-bg:#fff;" tabindex="0" dir="ltr"><code><span class="line"><span>$ hnl typecheck vec.hnl   # ok</span></span></code></pre></div><p><code>id_io</code> never mentions <code>s</code> in the body — it is the effect row of whatever function you pass. Applying it to <code>print</code> solves <code>s := {puts: String ~&gt; Unit}</code> automatically. <code>{s : Sig}</code> declares the sort explicitly when inference needs a hint.</p><h2 id="what-runs-vs-what-is-type-level" tabindex="-1">What runs vs. what is type-level <a class="header-anchor" href="#what-runs-vs-what-is-type-level" aria-label="Permalink to “What runs vs. what is type-level”">​</a></h2><table tabindex="0"><thead><tr><th>Surface</th><th><code>hnl typecheck</code></th><th><code>hnl run</code></th></tr></thead><tbody><tr><td><code>data</code> families + constructors</td><td>checked</td><td>constructors are values; <code>match</code> on them evaluates</td></tr><tr><td>Index arithmetic (<code>Vec(1+1)</code>)</td><td>computed during checking</td><td>n/a</td></tr><tr><td><code>match</code> refinement / unreachable arms</td><td>checked per branch</td><td>evaluates the matched arm</td></tr><tr><td><code>Path</code>, <code>refl</code>, <code>p # v</code>, <code>J</code></td><td>checked (proof objects)</td><td>type-level only</td></tr><tr><td><code>IO(sig)</code>, <code>handle … with</code></td><td>sig + coverage checked</td><td>interprets via real op impls</td></tr><tr><td>Implicit <code>{…}</code> binders</td><td>meta inserted + solved</td><td>erased</td></tr></tbody></table><h2 id="next-steps" tabindex="-1">Next steps <a class="header-anchor" href="#next-steps" aria-label="Permalink to “Next steps”">​</a></h2><ul><li><a href="./../explanation/arrow-calculus-kernel.html">The arrow calculus kernel</a> — why <code>~&gt;</code> and combinators are the whole computation model.</li><li><a href="./../explanation/graded-algebraic-theory.html">Graded algebraic theory</a> — the theory behind <code>IO(sig)</code> and grades.</li><li><a href="./../reference/">Reference</a> — judgment ops and type-rule data for engine authors.</li></ul>`,65)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};